// Re-export — many external callers import these types from Feed
// directly rather than reaching into ../types/../context. Keep the
// alias stable until the sweep is over.
export type { AgentProvider, ScrollInfo } from '@renderer/features/feed/types'
// NOTE: the `CodeRenderContext` re-export was removed (feed audit Finding 8).
// The canonical home is `@renderer/features/feed/context`, shared by feed,
// reader, preview, and provider rows; re-exporting it from the feed CONTAINER
// module coupled provider rows to Feed.tsx (which itself imports provider row
// dispatchers) and created a needless import cycle risk. All consumers now
// import it directly from `context`.

// -----------------------------------------------------------------------------
// Feed — Claude Code TUI-style inline rendering.
//
// Design rules (discussed with the user):
//   1. No bubbles. No cards. No role labels. Messages flow inline like a
//      terminal session — each block gets a single-char marker in the
//      accent color, content wraps with a hanging indent beside it.
//   2. User text → `❯`. Assistant text → `⏺`. Tool results and CC's
//      sub-items → `⎿`. Same markers CC's own TUI uses.
//   3. System entries (permission-mode, file-history-snapshot, hook
//      attachments) are hidden by default and only render when the
//      user opts in via settings.
//   4. Sharp everything — no border-radius, no shadows, no pills. The
//      visual rhythm comes entirely from the marker + hanging indent.
//
// Hanging indent implementation:
//   <div flex gap-3>
//     <span w-3 text-accent>⏺</span>
//     <div flex-1 min-w-0>...content wraps here...</div>
//   </div>
//
// Because the marker column is a fixed width and the content column is
// flex-1, long lines wrap under the content column only — they don't
// creep back under the marker. Standard hanging-indent pattern.
// -----------------------------------------------------------------------------

// COMPLETED_REMARK / STREAMING_REMARK moved to ../lib/remark-plugins.ts
// ProviderContext + ToolUseIndexContext + ToolResultIndexContext +
// CodeRenderContext moved to ../context.tsx — see those files for
// the full rationale. Feed.tsx re-exports CodeRenderContext above
// to keep external import paths stable.

// MarkdownPre / MarkdownCode / MARKDOWN_COMPONENTS moved to
// ./markdown/MarkdownComponents.tsx. TextProse and StreamingProse
// moved to ./markdown/Prose.tsx. Both are re-exported from
// ./markdown/index.ts — see those for the full rationale on why
// we override react-markdown's default <pre>/<code> renderers and
// why two remark plugin sets exist.
//
// buildToolUseIndex / buildToolResultIndex / extractToolCommand /
// toolResultText moved to ../lib/helpers.ts. AgentProvider and
// ScrollInfo types moved to ../types.ts; re-exported at the top of
// this file.

type Props = {
  usageLimitActions?: UsageLimitActions
  /** Session identity — used as the key for per-session scroll
   *  position persistence across Feed unmount/remount (tab switches).
   *  See `scrollPositions` below. */
  sessionId: string
  /** Which provider's row renderers to use. Required since #1177: the old
   *  `'claude'` default meant a caller that forgot it painted any provider
   *  with Claude's rows, silently. AgentFeed, the one mount, always knows. */
  provider: AgentProvider
  entries: Entry[]
  /**
   * The ownership-ledger pipeline's pre-decided, pre-ordered item list — the
   * ONLY source of Feed's rows since the Stage 3 cutover. The ledger owns
   * ordering and row ownership; its view bridge then proves post-correlation
   * paintability (desktop: TileLeaf via useLedgerFeedItems; phone: remote
   * SessionView via the same hook). Feed just paints. Kept nullable only so a
   * caller mid-migration can pass null
   * for an empty feed — there is no longer a legacy fallback path behind it.
   */
  renderItemsOverride?: FeedRenderItem[] | null
  /** The view bridge uses this exact resolver to classify absorbed committed
   * entries before Feed. Sharing it here means mounted Block rows reuse the
   * same WeakMap decision instead of parsing the operation a second time. */
  committedOperationDecisionOverride?: CommittedOperationDecisionResolver
  // NOTE: the `activityStatus` prop was removed (feed audit Deletion Candidate
  // 1). It was declared and destructured but never read inside Feed — once
  // `streamPhase` took over the in-feed WorkIndicator, the spinner verb text
  // stopped driving any rendering here. The runtime field still lives on
  // SessionRuntime for DebugPanel/status surfaces; only the dead Feed prop and
  // its TileLeaf pass-through are gone.
  /** Adapter-derived stream phase — drives the in-feed WorkIndicator.
   *  See SessionRuntime.streamPhase for the contract. */
  streamPhase?: StreamPhase
  streamPhasePendingToolName?: string | null
  streamPhasePendingToolUseId?: string | null
  turnStartedAt?: number | null
  tailMode?: boolean
  /**
   * UUID of the assistant entry currently highlighted by the
   * "Copy Assistant Message" picker. Null when the picker is not
   * active. Drives a 2px accent outline on the matching row and
   * auto-scrolls into view when the value changes.
   */
  pickerSelectedUuid?: string | null
  /**
   * UUID of the optimistic prompt row whose send has not settled yet (#1181).
   * That row paints dimmed with a `Sending…` caption until the provider
   * accepts or rejects the prompt.
   *
   * WHY a prop keyed by uuid and not a flag on the ledger row: "still sending"
   * is presentation over a row the ledger already decided to show. Putting it
   * in the candidate would make every send and every settle rebuild ledger
   * rows and bust the identity cache (D11) during the hottest repaint window.
   * It would also teach ordering and ownership about a state they must ignore.
   */
  pendingEntryUuid?: string | null
  /**
   * Instance id (`data-code-block-id`) of the code block currently
   * highlighted by the "Copy Code Block" picker. Null when that
   * picker is not active. Drives an accent outline on the matching
   * CodeBlock and auto-scrolls it into view when the value changes.
   */
  codeBlockSelectedId?: string | null
  workspaceRoot?: string | null
  /** Called on every scroll tick with the current position. */
  onScrollInfo?: (info: ScrollInfo) => void
  /** User-originated engagement with the feed surface. Programmatic
   *  auto-scroll must not call this; unread badges should clear only
   *  when the user actually touches the session. */
  onUserEngagement?: () => void
  hasOlderHistory?: boolean
  loadingOlderHistory?: boolean
  onLoadOlderHistory?: () => Promise<void>
  semanticHistory?: SemanticLiveTurn[]
  semanticTurn?: SemanticLiveTurn | null
  /** True while the owning session is replaying a bulk bootstrap
   *  burst. Feed uses it to suspend auto-scroll pinning and the
   *  IntersectionObserver-driven lazy mount, avoiding the layout
   *  cascade that otherwise makes resume feel like "scrolling
   *  through the whole conversation." */
  bootstrapping?: boolean
  scrollToLatestRequest?: number
  /** Incremental tool indices maintained by workspaceStore. Feed
   *  used to rebuild these via `useMemo([entries])` per render, which
   *  was O(N) per append and O(N²) per bootstrap burst. Passed in
   *  now from the runtime — the store grows them at ingest time. */
  toolUseIndex?: Map<string, ToolUseBlock>
  toolResultIndex?: Map<string, ToolResultBlock>
  /** Monotonic invalidation token for the two maps above (feed audit Finding 1).
   *  The runtime mutates the maps in place and keeps a STABLE reference, so the
   *  bare map identity can never tell React context consumers that a cross-entry
   *  tool_use↔tool_result pairing changed. The runtime bumps this whenever a
   *  pairing actually moves; Feed clones the map (cheap, only on bump) so the
   *  context value identity changes and memoized rows — most visibly a
   *  GitCardRow waiting on its paired result — repaint. Absent for preview
   *  surfaces that pass no runtime maps (they rebuild from `entries`). */
  toolIndexVersion?: number
  /** Subagent fleet for this session, keyed by parent `Agent` tool_use id.
   *  Threaded from runtime.subAgents and provided to rows via
   *  SubAgentsContext so the `Agent` card can render live status + drill-in. */
  subAgents?: Record<string, SubAgentState>
  /** Live AUQ screen condition, used only to gate clickability in the inline
   *  semantic row. Undefined means no snapshot yet; null means latest snapshot
   *  positively lacks the picker. Rendering still gates on the transcript block. */
  askUserQuestionState?: ClaudeAskUserQuestionState | null
  onDebugLog?: (entry: {
    layer: 'RENDER'
    kind: string
    summary: string
    data?: unknown
  }) => void
}

/** Exported for AgentFeed (#1177), which maps a runtime onto these props
 *  once for every surface that paints an agent feed. */
export type FeedProps = Props

// VisibleDecision + DebugVisibleRow moved to ../types.ts.
// debugKeyForEntry + debugLabelForEntry moved to ../lib/helpers.ts.

// 2026-04-20: shouldSuppressSemanticTurnForCommittedTail and its two
// helpers (textFromConversationEntry, normalizeRenderableText) were
// deleted here. They were a narrow guardrail for one proven duplicate
// class on Codex: committed assistant entry + rollout-sourced live
// semantic turn painting the same sentence twice during the gap
// between rollout publishing `turn.text` and committed sealing the
// live owner.
//
// That duplicate class is now prevented at its source. The ghost
// reducer (`reconcileUpstream` in src/renderer/src/session-runtime/ghosts.ts)
// supersedes Codex text ghosts by rollout response id once the
// rollout mapper stamps `codexTurnId` on committed entries
// (src/renderer/src/workspace/workspaceStore.ts::codexTurnIdFromRollout
// + stampCodexTurnId). The live view and the merged feed are split
// by turn ownership (src/renderer/src/session-runtime/mergedEntries.ts), so
// there is no longer any path by which the same assistant text can
// reach both surfaces at once.
//
// See docs/superpowers/plans/2026-04-20-rendering-fixes.md Task 6.

// ScrollPosition type + scrollPositions map moved to ../scroll.ts
// and ../types.ts respectively — see those files for the "why persist
// scroll state outside the component tree" rationale.

// -----------------------------------------------------------------------------
// Memoization strategy — the whole reason this file is fast enough to type in
// -----------------------------------------------------------------------------
//
// Parsing markdown through unified (remark-parse → remark-gfm → rehype-
// highlight → highlight.js) is EXPENSIVE. A single assistant message with
// a handful of code blocks easily takes 5-15ms per ReactMarkdown call,
// and a scrolled-back feed can contain dozens of them. Without memoization,
// every keystroke in the composer input (which is a sibling component
// living inside the same TileLeaf) triggers a TileLeaf re-render, which
// re-renders <Feed>, which re-parses every single markdown block from
// scratch. That's 100ms+ of blocking work between the browser input event
// and the next paint — the input literally cannot update until the
// markdown finishes, and typing becomes unusable.
//
// The fix is a two-layer memo:
//
//   1. `Feed` itself is memoized. When the parent re-renders for a reason
//      unrelated to feed content (user typing, focus toggle, split resize,
//      picker visibility change), Feed sees the same committed-entry
//      and semantic-turn references, and React.memo's default shallow
//      compare bails the entire subtree out. Zero markdown work happens.
//
//   2. Every row component (`EntryRow`, `ConversationRow`, `TextProse`,
//      `JsonToolRow`, `ToolResultRow`) is individually memoized. Even when
//      Feed DOES need to re-render (new entry lands, streaming frame
//      ticks), existing rows receive the exact same entry/block/text
//      reference they had last time and skip. Only the genuinely new
//      row does parse work. This matters because entries are appended,
//      not replaced — we spread `[...current.entries, newOne]`, so the
//      array reference is fresh but every existing element is stable.
//
// TextProse/StreamingProse are the hottest leaf; memoizing them by the
// `text` string is the single biggest win because ReactMarkdown itself
// has no memo and re-parses on every call.
//
// Live semantic rows are not flattened into committed entries on purpose.
// They re-render when the semantic reducer changes the active/history
// turns, but the markdown leaf (`StreamingProse`) is still memoed by
// text so identical consecutive semantic ticks are cheap.

export const Feed = memo(FeedImpl)

function FeedImpl({
  usageLimitActions,
  sessionId,
  provider,
  entries,
  renderItemsOverride = null,
  committedOperationDecisionOverride,
  streamPhase = 'idle',
  streamPhasePendingToolName = null,
  streamPhasePendingToolUseId = null,
  turnStartedAt = null,
  tailMode = false,
  pickerSelectedUuid = null,
  pendingEntryUuid = null,
  codeBlockSelectedId = null,
  workspaceRoot = null,
  onScrollInfo,
  onUserEngagement,
  hasOlderHistory = false,
  loadingOlderHistory = false,
  onLoadOlderHistory,
  semanticHistory = [],
  semanticTurn = null,
  bootstrapping = false,
  scrollToLatestRequest = 0,
  toolUseIndex: toolUseIndexProp,
  toolResultIndex: toolResultIndexProp,
  toolIndexVersion = 0,
  subAgents = {},
  askUserQuestionState,
  onDebugLog,
}: Props) {
  // From the host, not the app store (#1177): the store is desktop state the
  // phone could only fake with an untyped stub, and this switch is the ONE
  // thing the whole Feed subtree read from it.
  const { renderingDebugMode } = useRendererHost()
  // Scroll container owned by Feed itself — not by TileLeaf — so the
  // sticky-bottom logic below can own its own scroll listener without
  // reaching up the tree. TileLeaf's wrapper is just a flex cell and
  // no longer sets overflow-auto; see TileLeaf.tsx for the pair.
  //
  // Why this is load-bearing: active semantic turns can update many
  // times per second. A naive "scroll to bottom on every render" effect
  // yanks the viewport down whenever text/tool deltas arrive, making it
  // impossible for the user to scroll up and read earlier content.
  // Worth preserving the original production diagnosis: "scrolling
  // doesn't even work, it snaps me back to the bottom super glitchly."
  // That's exactly the behavior the old unconditional effect produced.
  //
  // The fix is two-part:
  //   1. Track "is the user near the bottom right now" in a ref
  //      that's updated by a scroll listener. "Near" = within 48px
  //      of the bottom; the pad absorbs sub-pixel rounding and the
  //      natural momentum overshoot when new rows land.
  //   2. Only auto-scroll when the ref is true. If the user has
  //      scrolled up, stickyBottom becomes false, and subsequent
  //      updates stop forcing the viewport down. When the user
  //      scrolls back to the bottom, the ref flips true again and
  //      auto-scroll resumes.
  //
  // Using a ref (not state) for stickyBottom is deliberate: we don't
  // want a React re-render on every scroll tick, only a read in the
  // auto-scroll effect. Scroll events fire on EVERY pixel, so this
  // matters.
  const scrollerRef = useRef<HTMLDivElement>(null)
  const endRef = useRef<HTMLDivElement>(null)
  // Restore stickyBottom from the persisted map on first render so
  // the auto-scroll effect below makes the right decision without
  // needing to wait for the scroll listener to run. Defaults to
  // true for brand-new sessions (no saved position yet).
  const stickyBottomRef = useRef(
    scrollPositions.get(sessionId)?.stickyBottom ?? true,
  )
  const loadingOlderRef = useRef(false)
  // Was there an existing saved scroll position for this session when
  // this Feed instance mounted? Used to distinguish "restore the
  // user's deliberate scrolled-up position" from "brand-new/resumed
  // session should land at latest content even if stickyBottom got
  // transiently knocked false during bootstrap."
  const hadSavedPositionOnMountRef = useRef(scrollPositions.has(sessionId))
  // Previous scrollTop, used to distinguish "the user started
  // scrolling upward" from incidental near-bottom jitter. This is
  // load-bearing during active turns: with the old "gap < 48"
  // heuristic alone, a tiny upward wheel tick still counted as
  // sticky, and the next ~60 Hz screen update snapped the feed right
  // back down before the user could accumulate enough distance to
  // escape. Any real upward movement should break follow
  // immediately; re-follow only when the user intentionally returns
  // near the bottom.
  const lastScrollTopRef = useRef(0)

  // Restore the saved scroll position on mount — synchronously, via
  // useLayoutEffect, so the browser never paints the scroller at
  // scrollTop=0 before we restore. Using useEffect here would flash
  // the top of the feed for one frame before the restore landed.
  //
  // Three cases:
  //   1. No saved entry → this is the first time we've mounted for
  //      this session (or the map was just cleared). Default to
  //      "stuck at bottom" — for a freshly-opened feed the user
  //      wants to see the most recent content, just like opening a
  //      terminal or a chat window.
  //   2. Saved stickyBottom: true → the user was at the bottom when
  //      they left. Content may have grown while we were unmounted
  //      (new entries appended to runtime.entries even though Feed
  //      wasn't rendering), so we pin to the NEW scrollHeight, not
  //      the old scrollTop.
  //   3. Saved stickyBottom: false → restore the exact saved
  //      scrollTop. Content height on remount matches save time
  //      (because unmount freezes new entries from growing the
  //      unmounted scroller) so this is pixel-accurate.
  //
  // The sessionId dep is load-bearing: if the user resumes a
  // different session in the same pane slot, we need to re-restore
  // from the new key. Today it's effectively a mount-only effect.
  useLayoutEffect(() => {
    const el = scrollerRef.current
    if (!el) return
    hadSavedPositionOnMountRef.current = scrollPositions.has(sessionId)
    if (tailMode) {
      el.scrollTop = el.scrollHeight
      stickyBottomRef.current = true
      lastScrollTopRef.current = el.scrollTop
      return
    }
    const saved = scrollPositions.get(sessionId)
    if (!saved || saved.stickyBottom) {
      // Case 1 or 2: pin to bottom. We do this synchronously in
      // useLayoutEffect so the browser commits the scrollTop change
      // in the SAME paint as the initial content render. Without
      // that, the first paint shows scrollTop=0 (top) and the next
      // tick scrolls down — visibly a "starts at top, jumps to
      // bottom" flash on every tab switch, which is the exact bug
      // the user flagged.
      el.scrollTop = el.scrollHeight
      stickyBottomRef.current = true
      lastScrollTopRef.current = el.scrollTop
    } else {
      // Case 3: restore exact position.
      el.scrollTop = saved.scrollTop
      stickyBottomRef.current = false
      lastScrollTopRef.current = el.scrollTop
    }
  }, [sessionId, tailMode])

  // One scroll listener for the container. Updates stickyBottomRef
  // imperatively AND persists the position into the module-level
  // map so a later unmount/remount can restore it.
  //
  // CRITICAL: we DO NOT call onScroll() synchronously on mount.
  // That was the original bug — at mount time the scroller has
  // scrollTop=0 and scrollHeight=full-content, so gap > 48 and the
  // handler would stamp stickyBottom=false INTO THE REF AND THE
  // PERSISTED MAP before the layout effect above had a chance to
  // scroll to the bottom. Then the auto-scroll effect below would
  // see stickyBottom=false and skip, leaving the viewport stuck at
  // the top. The layout effect sets stickyBottomRef explicitly, so
  // the scroll listener only needs to react to actual user scrolls.
  useEffect(() => {
    const el = scrollerRef.current
    if (!el) return
    const onScroll = () => {
      if (tailMode) {
        el.scrollTop = el.scrollHeight
        stickyBottomRef.current = true
        lastScrollTopRef.current = el.scrollTop
        // WHY tailing deliberately does NOT persist into scrollPositions:
        // this branch runs on the scroll event that our own re-pin just caused,
        // so writing here would overwrite the user's pre-tail reading position
        // with {bottom, stickyBottom: true} — and only in the case where it
        // mattered, since a pane already at the bottom emits no scroll event.
        // The position then could not come back: the layout effect above reads
        // this map when tail turns off, saw stickyBottom true, and re-pinned to
        // the bottom with stickyBottomRef latched, so the feed kept following
        // something the user had scrolled away from.
        //
        // Leaving the map untouched makes tail non-destructive: the pre-tail
        // entry survives, and turning tail off takes the "restore exact
        // position" branch, which also clears stickyBottomRef. Found reviewing
        // Tail All (#579), which widened the blast radius of this from one pane
        // to every visible pane at once, but the bug predates it and this fixes
        // per-session Tail too.
        if (onScrollInfo) onScrollInfo({ fraction: 0 })
        return
      }
      const gap = el.scrollHeight - (el.scrollTop + el.clientHeight)
      const scrollingUp = el.scrollTop < lastScrollTopRef.current
      const nearBottom = gap < 48
      stickyBottomRef.current =
        scrollingUp && gap > 0 ? false : nearBottom
      lastScrollTopRef.current = el.scrollTop
      scrollPositions.set(sessionId, {
        scrollTop: el.scrollTop,
        stickyBottom: stickyBottomRef.current,
      })
      // Push scroll position to parent for the scroll indicator.
      // fraction=0 at bottom, fraction=1 at top.
      if (onScrollInfo) {
        const maxScroll = el.scrollHeight - el.clientHeight
        const fraction = maxScroll > 0
          ? 1 - (el.scrollTop / maxScroll)
          : 0
        onScrollInfo({ fraction })
      }

      if (
        el.scrollTop < 160 &&
        hasOlderHistory &&
        !loadingOlderHistory &&
        !loadingOlderRef.current &&
        !tailMode &&
        onLoadOlderHistory
      ) {
        loadingOlderRef.current = true
        const beforeHeight = el.scrollHeight
        const beforeTop = el.scrollTop
        void onLoadOlderHistory()
          .then(() => {
            requestAnimationFrame(() => {
              const next = scrollerRef.current
              if (!next) return
              const delta = next.scrollHeight - beforeHeight
              next.scrollTop = beforeTop + Math.max(0, delta)
              lastScrollTopRef.current = next.scrollTop
            })
          })
          .finally(() => {
            loadingOlderRef.current = false
          })
      }
    }
    el.addEventListener('scroll', onScroll, { passive: true })
    return () => el.removeEventListener('scroll', onScroll)
  }, [
    sessionId,
    onScrollInfo,
    tailMode,
    hasOlderHistory,
    loadingOlderHistory,
    onLoadOlderHistory,
  ])

  // Auto-scroll on content changes, but ONLY when sticky. The effect
  // runs on every change that would grow the feed (a new committed
  // entry) or move the semantic streaming tail. If the
  // user is scrolled up, we skip — they're reading earlier content
  // and we don't want to yank them back.
  //
  // Include cheap fingerprints of the current semantic turn and
  // bounded semantic history so the effect re-runs when semantic
  // deltas land, not only when committed entries append.
  // WHY semanticTurnScrollSignal and not just turnId:text.length:blockCount
  // (feed audit Finding 2): the old signal missed per-block streaming growth
  // (tool output / thinking / reasoning deltas inside an existing block), so the
  // sticky-bottom effect below would not re-pin while a row visibly grew. The
  // helper folds in each block's content lengths and status so this effect fires
  // on the common streaming path. It is a scroll-invalidation token only.
  const semanticTurnSignal = semanticTurn ? semanticTurnScrollSignal(semanticTurn) : ''
  // See LiveUnresolvedQuestionsContext for why the committed AskUserQuestion
  // card needs this. Current turn only, by design.
  //
  // WHY a string signature in between: `semanticTurn` is replaced on every
  // streamed delta, so memoising the Set on it would hand every consumer a
  // fresh identity per token and re-render each committed question row for
  // nothing. The signature only changes when the set of unresolved ids does.
  const liveUnresolvedQuestionSignature = useMemo(() => {
    if (!semanticTurn) return ''
    const ids: string[] = []
    for (const block of Object.values(semanticTurn.blocks)) {
      if (block.toolName === 'AskUserQuestion' && block.resultAt == null && block.toolUseId) {
        ids.push(block.toolUseId)
      }
    }
    return ids.sort().join('\n')
  }, [semanticTurn])
  const liveUnresolvedQuestionIds = useMemo(
    () => new Set(liveUnresolvedQuestionSignature ? liveUnresolvedQuestionSignature.split('\n') : []),
    [liveUnresolvedQuestionSignature],
  )
  const semanticHistorySignal = semanticHistory
    .map(semanticTurnScrollSignal)
    .join('|')
  const workspaceVisible = useAgentTerminalOwnerVisible()
  useEffect(() => {
    // During a bulk bootstrap burst we skip per-append auto-scroll.
    // The pin-once-on-transition effect below lands us at the bottom
    // in a single operation after the burst ends — otherwise every
    // entry appended during the burst would pin-scroll and wake up
    // the LazyEntry observer cascade. See docs/superpowers/plans/
    // 2026-04-15-bootstrap-replay-perf.md.
    if (bootstrapping) return
    // While the workspace is retained under display:none (editor fullscreen,
    // Reader/Spotlight/Settings — #752) scrollHeight is 0 and a pin would be
    // a no-op; the flag in the deps makes the reveal re-run this effect, so
    // a sticky-bottom feed that grew while hidden comes back at the bottom.
    if (!workspaceVisible) return
    if (!tailMode && !stickyBottomRef.current) return
    // scrollTop = scrollHeight pins to bottom without the smooth-scroll
    // overshoot scrollIntoView sometimes produces. Direct, instant,
    // no animation frames.
    const el = scrollerRef.current
    if (el) el.scrollTop = el.scrollHeight
  }, [entries.length, tailMode, semanticTurnSignal, semanticHistorySignal, bootstrapping, workspaceVisible])

  // Pin-once on the bootstrap → live transition. Runs exactly once per
  // transition thanks to the previous-value ref: we read the prior
  // value, compare, pin if we just left bootstrap mode, then store the
  // new value for next time. No dependency on `entries.length` so the
  // effect does not fire on subsequent live appends — those go
  // through the regular auto-scroll effect above.
  const prevBootstrappingRef = useRef(false)
  useEffect(() => {
    if (prevBootstrappingRef.current && !bootstrapping) {
      const el = scrollerRef.current
      // Fresh/resumed sessions with no saved scroll position should
      // ALWAYS land on the latest content after the bootstrap burst.
      // Relying purely on stickyBottomRef here is fragile because the
      // initial mount/placeholder/lazy-load sequence can transiently
      // mark the feed non-sticky before the first real user scroll.
      // That leaves the viewport stranded above the eager tail: the
      // exact "blank until I scroll down a couple pages" symptom.
      const shouldForceInitialBottom =
        !hadSavedPositionOnMountRef.current && !tailMode
      if (el && (tailMode || stickyBottomRef.current || shouldForceInitialBottom)) {
        el.scrollTop = el.scrollHeight
        stickyBottomRef.current = true
        lastScrollTopRef.current = el.scrollTop
        scrollPositions.set(sessionId, {
          scrollTop: el.scrollTop,
          stickyBottom: true,
        })
        if (onScrollInfo) onScrollInfo({ fraction: 0 })
      }
    }
    prevBootstrappingRef.current = bootstrapping
  }, [bootstrapping, onScrollInfo, sessionId, tailMode])

  // When the picker selection changes, smoothly tween the scroller
  // so the highlighted entry centers in the viewport.
  //
  // We do NOT use native scrollIntoView({behavior:'smooth'}) because:
  //   - With block:'nearest' it no-ops when the target is already on
  //     screen, so rapid arrow presses after a manual scroll land on
  //     already-visible entries and produce zero motion (user report:
  //     "my arrow key does nothing after I scroll").
  //   - With block:'center' native smooth scroll was observably shaky
  //     here — the feed's own scroll listener fires on every frame of
  //     the animation and was fighting the browser's scroll queue.
  //
  // A custom rAF tween is ~20 lines, interrupt-safe (new target
  // cancels any in-flight animation), and completely independent of
  // whatever the scroll listener is doing.
  const scrollAnimFrameRef = useRef<number | null>(null)
  useEffect(() => {
    if (!pickerSelectedUuid) return
    const root = scrollerRef.current
    if (!root) return
    const target = root.querySelector(
      `[data-entry-uuid="${pickerSelectedUuid}"]`,
    ) as HTMLElement | null
    if (!target) return

    // Compute desired scrollTop so the target's vertical center aligns
    // with the scroller's vertical center. Clamp to the scroller's
    // scrollable range so we don't try to scroll past start/end.
    const targetCenter = target.offsetTop + target.offsetHeight / 2
    const desired = targetCenter - root.clientHeight / 2
    const maxScroll = root.scrollHeight - root.clientHeight
    const to = Math.max(0, Math.min(maxScroll, desired))
    const from = root.scrollTop
    const distance = to - from
    if (Math.abs(distance) < 1) return

    // Cancel any in-flight animation so rapid Up/Down presses don't
    // compound into a runaway scroll.
    if (scrollAnimFrameRef.current !== null) {
      cancelAnimationFrame(scrollAnimFrameRef.current)
      scrollAnimFrameRef.current = null
    }

    const duration = 180
    const startTime = performance.now()
    const ease = (t: number) => 1 - Math.pow(1 - t, 3) // easeOutCubic

    const step = (now: number) => {
      const elapsed = now - startTime
      const t = Math.min(1, elapsed / duration)
      root.scrollTop = from + distance * ease(t)
      if (t < 1) {
        scrollAnimFrameRef.current = requestAnimationFrame(step)
      } else {
        scrollAnimFrameRef.current = null
      }
    }
    scrollAnimFrameRef.current = requestAnimationFrame(step)

    return () => {
      if (scrollAnimFrameRef.current !== null) {
        cancelAnimationFrame(scrollAnimFrameRef.current)
        scrollAnimFrameRef.current = null
      }
    }
  }, [pickerSelectedUuid])

  // Copy Code Block picker — highlight + scroll the selected block.
  //
  // WHY a separate effect from the assistant-entry one above, and why
  // the outline is applied imperatively here rather than as a JSX
  // class: the assistant picker highlights an ENTRY, and Feed already
  // renders a wrapper <div data-entry-uuid> per entry that it can add
  // an outline class to in JSX. A code block is a `CodeBlock` buried
  // deep inside rendered markdown / tool rows — there is no per-block
  // wrapper Feed controls. So we locate the block by its
  // `data-code-block-id` and toggle the outline classes on the node
  // directly; the cleanup removes them.
  //
  // The outline class list is the SAME tokens the entry picker uses
  // (line ~881) — keeping them identical means Tailwind's static
  // scan already emits the CSS, so `classList.add` is safe.
  //
  // Shares `scrollAnimFrameRef` with the assistant-picker scroll so a
  // tween from one picker is cancelled if the other starts; only one
  // picker is ever active at a time, so they never genuinely race.
  useEffect(() => {
    if (!codeBlockSelectedId) return
    const root = scrollerRef.current
    if (!root) return
    const target = root.querySelector(
      `[data-code-block-id="${codeBlockSelectedId}"]`,
    ) as HTMLElement | null
    if (!target) return

    const outline = ['outline', 'outline-2', 'outline-accent', 'outline-offset-2']
    target.classList.add(...outline)

    // Center the block in the scroller — same rAF tween as the
    // assistant-picker scroll effect (native smooth-scroll fought the
    // feed's own scroll listener; see the long note on that effect).
    const targetCenter = target.offsetTop + target.offsetHeight / 2
    const desired = targetCenter - root.clientHeight / 2
    const maxScroll = root.scrollHeight - root.clientHeight
    const to = Math.max(0, Math.min(maxScroll, desired))
    const from = root.scrollTop
    const distance = to - from
    if (Math.abs(distance) >= 1) {
      if (scrollAnimFrameRef.current !== null) {
        cancelAnimationFrame(scrollAnimFrameRef.current)
        scrollAnimFrameRef.current = null
      }
      const duration = 180
      const startTime = performance.now()
      const ease = (t: number) => 1 - Math.pow(1 - t, 3)
      const step = (now: number) => {
        const t = Math.min(1, (now - startTime) / duration)
        root.scrollTop = from + distance * ease(t)
        if (t < 1) {
          scrollAnimFrameRef.current = requestAnimationFrame(step)
        } else {
          scrollAnimFrameRef.current = null
        }
      }
      scrollAnimFrameRef.current = requestAnimationFrame(step)
    }

    return () => {
      target.classList.remove(...outline)
      if (scrollAnimFrameRef.current !== null) {
        cancelAnimationFrame(scrollAnimFrameRef.current)
        scrollAnimFrameRef.current = null
      }
    }
  }, [codeBlockSelectedId])

  useEffect(() => {
    if (scrollToLatestRequest === 0) return
    const el = scrollerRef.current
    if (!el) return
    if (scrollAnimFrameRef.current !== null) {
      cancelAnimationFrame(scrollAnimFrameRef.current)
      scrollAnimFrameRef.current = null
    }
    el.scrollTop = el.scrollHeight
    stickyBottomRef.current = true
    lastScrollTopRef.current = el.scrollTop
    scrollPositions.set(sessionId, {
      scrollTop: el.scrollTop,
      stickyBottom: true,
    })
    if (onScrollInfo) onScrollInfo({ fraction: 0 })
  }, [onScrollInfo, scrollToLatestRequest, sessionId])

  // Index EVERY tool_use block (not just the visible set) so tool_result
  // lookups still resolve even when some synthetic entries have been
  // filtered out. The index is cheap to
  // build (single pass) and the resulting Map is handed to result rows
  // via context.
  // Incremental indices live on the runtime and grow at entry-ingest time.
  //
  // WHY this is now a clone-on-version-bump and not a bare passthrough (feed
  // audit Finding 1): the runtime mutates these maps IN PLACE behind a stable
  // reference. Returning that reference straight through means the context
  // Provider value identity never changes when only a cross-entry pairing moves
  // (a tool_result landing in a later entry for a tool_use row mounted earlier),
  // so memoized rows like GitCardRow keep painting their stale running/empty
  // state. Cloning into a fresh Map gives the context a new identity that forces
  // those consumers to re-read. The clone is O(N) but the dependency is
  // `toolIndexVersion` (bumped only on a REAL map change), NOT `entries`, so it
  // runs once per actual tool change — not once per append. That preserves the
  // bootstrap-burst performance win this incremental index was built for.
  //
  // The fallback path (preview / no runtime maps) rebuilds from `entries` and is
  // isolated below so the live path never depends on `entries`.
  const fallbackToolUseIndex = useMemo(
    () => (toolUseIndexProp ? null : buildToolUseIndex(entries)),
    [toolUseIndexProp, entries],
  )
  const fallbackToolResultIndex = useMemo(
    () => (toolResultIndexProp ? null : buildToolResultIndex(entries)),
    [toolResultIndexProp, entries],
  )
  const toolUseIndex = useMemo(
    () => (toolUseIndexProp ? new Map(toolUseIndexProp) : fallbackToolUseIndex!),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- toolIndexVersion is the
    // intentional invalidation token for the in-place-mutated prop map.
    [toolUseIndexProp, toolIndexVersion, fallbackToolUseIndex],
  )
  const toolResultIndex = useMemo(
    () =>
      toolResultIndexProp ? new Map(toolResultIndexProp) : fallbackToolResultIndex!,
    // eslint-disable-next-line react-hooks/exhaustive-deps -- see above.
    [toolResultIndexProp, toolIndexVersion, fallbackToolResultIndex],
  )
  const localCommittedOperationDecision = useMemo(
    () => createCommittedOperationDecisionResolver(
      getRendererProviderCapabilities(provider).renderOperation,
    ),
    // WHY index identities are deliberately absent: the resolver's WeakMap is
    // already keyed by the immutable tool-use object and compares the exact
    // paired result object. Replacing this resolver for an unrelated map
    // append erased every older decision and repeatedly reparsed large Agent
    // Code results. A real result arrival changes that pair's result identity,
    // so it still invalidates precisely the affected decision. Provider is the
    // only lifetime boundary because it selects a different adapter chain.
    [provider],
  )
  const committedOperationDecision = committedOperationDecisionOverride ?? localCommittedOperationDecision

  // The shared feed transports a join map but never recognizes the provider's
  // transcript envelope. This registry call is the cutover boundary that keeps
  // Claude XML out of Codex/OpenCode while preserving cross-entry correlation.
  const taskNotifications = useMemo(
    () =>
      getRendererProviderCapabilities(provider).collectTaskNotifications?.(entries) ??
      new Map(),
    [entries, provider],
  )

  // #491: `committedProjection` (deriveFeedCommittedProjection) is deleted — it
  // existed ONLY to feed SemanticStreamingTurn's committedAssistantText for its
  // in-component dedup. The ledger now owns that suppression, and
  // SemanticStreamingTurn is gone, so Feed no longer derives any committed
  // projection of its own.

  // Stage 3 cutover (2026-07): the ownership ledger is the SOLE order/owner
  // core; its provider-aware view bridge adds the post-correlation paint
  // verdict that entry-grain candidates cannot carry.
  // Feed no longer derives its own render model — both the desktop (TileLeaf)
  // and the phone (remote SessionView) hand it the ledger's pre-decided,
  // pre-ordered items via renderItemsOverride, and `feedRenderModelFromItems`
  // only attaches the two debug side-products. The old in-Feed
  // deriveFeedRenderModel branch (the second decision-maker this rewrite
  // exists to kill) and its perf metric are deleted. `?? []` is pure
  // defense — both live callers always pass an array.
  const renderModel = useMemo(
    () => feedRenderModelFromItems(renderItemsOverride ?? [], provider),
    [renderItemsOverride, provider],
  )

  const visibleDecisions = renderModel.visibleDecisions
  const renderItems = renderModel.items
  const renderedRows = renderModel.debugRows
  const visibleEntryCount = renderItems.filter(item => item.type === 'entry').length
  // #491: semantic items are now block-level (semantic-block/-collapsed-activity/
  // -text), each tagged with its turn's owner. Derive the same debug signals the
  // old turn-level items exposed — unique history turnIds, and "is the current
  // turn on screen" — from the block items' owner+turnId.
  const renderedSemanticHistoryTurnIds = useMemo(() => {
    const seen = new Set<string>()
    const ids: string[] = []
    for (const item of renderItems) {
      if (
        (item.type === 'semantic-block' ||
          item.type === 'semantic-collapsed-activity' ||
          item.type === 'semantic-text') &&
        item.owner === 'semantic-history' &&
        !seen.has(item.turnId)
      ) {
        seen.add(item.turnId)
        ids.push(item.turnId)
      }
    }
    return ids
  }, [renderItems])
  const renderedSemanticHistorySignature = renderedSemanticHistoryTurnIds.join('\u0000')
  // The current live turn IS rendered iff any block item carries owner
  // 'semantic-current'. WorkIndicator's tool-hint reads the full turn, which
  // Feed already has as the `semanticTurn` prop — return that when present.
  const renderedSemanticTurn = useMemo(() => {
    const currentOnScreen = renderItems.some(
      item =>
        (item.type === 'semantic-block' ||
          item.type === 'semantic-collapsed-activity' ||
          item.type === 'semantic-text') &&
        item.owner === 'semantic-current',
    )
    return currentOnScreen ? semanticTurn : null
  }, [renderItems, semanticTurn])

  const previousRenderedRowsRef = useRef<DebugVisibleRow[] | null>(null)
  const previousRenderDebugSignatureRef = useRef<string | null>(null)

  useEffect(() => {
    if (!onDebugLog) return
    const previous = previousRenderedRowsRef.current
    const renderDebugSignature = JSON.stringify({
      entryCount: entries.length,
      visibleEntryCount,
      itemKeys: renderedRows.map(row => row.key),
      semanticTurnId: semanticTurn?.turnId ?? null,
      semanticHistoryTurnIds: renderedSemanticHistoryTurnIds,
      streamPhase,
    })
    const prevKeys = new Set(previous?.map(row => row.key) ?? [])
    const nextKeys = new Set(renderedRows.map(row => row.key))
    const added = renderedRows.filter(row => !prevKeys.has(row.key))
    const removed = (previous ?? []).filter(row => !nextKeys.has(row.key))
    const hidden = visibleDecisions
      .filter(item => !item.visible)
      .slice(-12)
      .map(item => ({
        key: item.key,
        label: debugLabelForEntry(item.entry),
        reason: item.reason,
      }))
    const changed =
      previous === null ||
      previousRenderDebugSignatureRef.current !== renderDebugSignature ||
      added.length > 0 ||
      removed.length > 0 ||
      previous.length !== renderedRows.length ||
      previous.some((row, index) => row.key !== renderedRows[index]?.key)
    if (!changed) return
    onDebugLog({
      layer: 'RENDER',
      kind: 'visible_rows',
      summary:
        previous === null
          ? `initial rows ${renderedRows.length}`
          : `rows ${previous.length} -> ${renderedRows.length} (+${added.length} -${removed.length})`,
      data: {
        rows: renderedRows,
        added,
        removed,
        hidden,
        entryCount: entries.length,
        visibleEntryCount,
        semanticTurnId: semanticTurn?.turnId ?? null,
        semanticHistoryTurnIds: renderedSemanticHistoryTurnIds,
        streamPhase,
      },
    })
    previousRenderedRowsRef.current = renderedRows
    previousRenderDebugSignatureRef.current = renderDebugSignature
  }, [entries.length, onDebugLog, renderedRows, renderedSemanticHistorySignature, renderedSemanticHistoryTurnIds, semanticTurn?.turnId, streamPhase, visibleDecisions, visibleEntryCount])

  const renderFeedItem = (item: FeedRenderItem) => {
    switch (item.type) {
      case 'provider-notice':
        return (
          <RenderDebugBoundary key={item.key} snapshot={{ sourcePlane: item.sourcePlane === 'committed' ? 'feed-entry' : 'feed-semantic', lifecycle: 'visible', eventType: 'provider-notice', input: item.notice, routingTrace: [{ id: 'ledger-provider-notice', condition: 'Which provider status owns this notice?', outcome: item.key }] }}>
            <UsageLimitNoticeView notice={item.notice} sessionRunId={item.sessionRunId} actions={usageLimitActions} />
          </RenderDebugBoundary>
        )
      case 'entry': {
        const e = item.entry
        const uuid = e.uuid
        const selected =
          pickerSelectedUuid != null && uuid === pickerSelectedUuid
        // A pending row is by construction the newest prompt, so it always
        // mounts eagerly; skipping LazyEntry also keeps the caption from
        // appearing before the row it describes.
        const pending = pendingEntryUuid != null && uuid === pendingEntryUuid
        // WHY eager rendering keys off committed-entry ordinal, not
        // render-item index: semantic/work rows now live in the
        // same ordered list, but markdown parse cost still belongs to
        // committed entries. Counting non-entry rows here would make a
        // busy turn accidentally lazy-mount the newest committed prompt.
        // WHY use the post-absorption ordinal: the ledger's entryOrdinal still
        // counts protocol-only result entries. Comparing that sparse number to
        // the painted count makes an old tail increasingly eager as invisible
        // entries accumulate, defeating LazyEntry on long command sessions.
        const eager = item.entryOrdinal >= visibleEntryCount - EAGER_TAIL
        return (
          <RenderDebugBoundary
            key={item.key}
            snapshot={{
              sourcePlane: 'feed-entry',
              lifecycle: 'visible',
              eventType: e.type,
              input: e,
              routingTrace: [{
                id: 'ledger-entry',
                condition: 'Which ownership-ledger item supplied this committed entry?',
                outcome: item.key,
              }],
            }}
          >
            <div
              data-entry-uuid={uuid ?? undefined}
              className={
                selected
                  ? 'outline outline-2 outline-accent outline-offset-2 transition-[outline-color] duration-150'
                  : undefined
              }
            >
              {pending ? (
                // Dimmed, not hidden or badged elsewhere: the prompt is shown
                // in the exact place and form it will keep once accepted, so
                // settling is only an opacity change and nothing jumps. The
                // caption says what the dimming means. aria-busy tells
                // assistive tech the same thing the opacity tells sighted users.
                <div className="opacity-50 transition-opacity duration-150" aria-busy="true">
                  <EntryRow entry={e} />
                  {/* 22px = MarkerRow's marker column (w-3) plus its gap-2.5,
                      so the caption sits under the prompt text, not the ❯. */}
                  <div className="mt-0.5 pl-[22px] text-[10px] text-muted">Sending…</div>
                </div>
              ) : (
                <LazyEntry
                  eager={eager}
                  suspended={bootstrapping}
                  scrollerRef={scrollerRef}
                >
                  <EntryRow entry={e} />
                </LazyEntry>
              )}
            </div>
          </RenderDebugBoundary>
        )
      }
      case 'absorbed-entry':
        // The view bridge already recorded the provider-owned absorption in
        // visibleDecisions. Mounting its Blocks here would restore the exact
        // history-proportional React work and invisible flex children this
        // explicit data item exists to remove.
        return null
      case 'semantic-block':
        // #491: the ledger already decided this block is visible; the row is a
        // pure drawer (no suppression). SemanticLiveBlockRow renders the exact
        // per-kind streaming affordances it always did.
        return (
          <RenderDebugBoundary
            key={item.key}
            snapshot={{
              sourcePlane: 'feed-semantic',
              lifecycle: item.block.finalized ? 'input-complete' : 'prefix',
              eventType: item.block.kind,
              input: item.block,
              routingTrace: [{
                id: 'ledger-semantic',
                condition: 'Which ownership-ledger item supplied this semantic block?',
                outcome: item.key,
              }],
            }}
          >
            <SemanticLiveBlockRow
              block={item.block}
              toolState={item.toolState}
            />
          </RenderDebugBoundary>
        )
      case 'semantic-collapsed-activity':
        return <SemanticCollapsedActivityRow key={item.key} unit={item.unit} />
      case 'semantic-text':
        // Blockless Codex/opencode turn text — the legacy no-blocks path.
        return (
          <MarkerRow key={item.key} marker="⏺">
            <StreamingProse text={item.text} />
          </MarkerRow>
        )
      case 'work':
        return (
          <WorkIndicator
            key={item.key}
            phase={item.phase}
            turnStartedAt={turnStartedAt}
            toolName={item.toolName}
            toolHint={toolHintFromTurn(renderedSemanticTurn, item.toolUseId)}
          />
        )
      case 'sleep-interruption':
        // #963 decision Q1a: say why the turn stopped instead of leaving a
        // silent tail or a counter that kept running through the night.
        return (
          <MarkerRow key={item.key} marker="" tone="muted">
            <div className="py-0.5 text-[13px] leading-[1.55] text-muted">
              Interrupted while asleep
            </div>
          </MarkerRow>
        )
      case 'transport-interruption':
        // #1040: the same courtesy for a stream that died mid-answer. The
        // wording claims no cause — an Esc, a proxy timeout and an upstream
        // failure are indistinguishable from here, and the provider's own
        // error text says "Client disconnected." for all three.
        return (
          <MarkerRow key={item.key} marker="" tone="muted">
            <div className="py-0.5 text-[13px] leading-[1.55] text-muted">
              Interrupted before the response finished
            </div>
          </MarkerRow>
        )
      case 'empty':
        return (
          <div
            key={item.key}
            className="flex min-h-[240px] flex-1 items-center justify-center"
          >
            <div className="text-muted text-[12px]">
              {`waiting for ${getRendererProviderCapabilities(item.provider).name}…`}
            </div>
          </div>
        )
    }
  }

  // WHY provider value identity is stable: every CodeBlock consumes this context. Recreating the
  // object on unrelated feed ticks bypasses memoized row boundaries and wakes every mounted code
  // renderer during exactly the high-frequency semantic traffic this PR is trying to absorb.
  const codeRenderContextValue = useMemo(
    () => ({ sessionId, workspaceRoot }),
    [sessionId, workspaceRoot],
  )

  return (
    <ProviderContext.Provider value={provider}>
      {/* Shape-capture binding (Phase 2, PR #555): carries {sessionId, provider}
          to the observation call sites in Block/EntryRow/SemanticLiveBlockRow and
          syncs the observer's armed state with main's recording truth on mount.
          Value is memoized per session — armed-ness deliberately lives OUTSIDE
          the context so toggling capture never re-renders the feed. */}
      <RenderingDebugProvider enabled={renderingDebugMode}>
        <RenderShapeCaptureProvider sessionId={sessionId} provider={provider}>
          <ToolUseIndexContext.Provider value={toolUseIndex}>
            <ToolResultIndexContext.Provider value={toolResultIndex}>
              <CommittedOperationDecisionContext.Provider value={committedOperationDecision}>
                <SubAgentsContext.Provider value={subAgents}>
                  <TaskNotificationsContext.Provider value={taskNotifications}>
                    <AskUserQuestionConditionContext.Provider value={askUserQuestionState}>
                      <LiveUnresolvedQuestionsContext.Provider value={liveUnresolvedQuestionIds}>
                        <CodeRenderContext.Provider value={codeRenderContextValue}>
                          <div
                            ref={scrollerRef}
                            data-render-debug-feed-root
                            // Declares this subtree as quotable text owned by
                            // this session, for "Reply to Selection". Anchored
                            // here rather than on the pane root so the composer
                            // and pane header stay OUT of scope — you should not
                            // be able to quote your own half-typed prompt back
                            // into itself. See features/reply-to-selection/lib/
                            // quoteScope.ts for the full reasoning.
                            data-quote-scope={sessionId}
                            // A keyboard Tab stop (ledger N13 / K2-4). The feed
                            // holds buttons, so Chromium's "scrollers without
                            // focusable children are focusable" rule never
                            // applied, and a keyboard user could not scroll the
                            // transcript at all: no arrows, no PgUp/PgDn, and
                            // End (jump-latest) only fired by accident when
                            // focus happened to sit on a feed button.
                            //
                            // WHY this is safe for the mouse path: clicking the
                            // feed now focuses this scroller instead of <body>,
                            // but useTypeToFocus already routes printable keys
                            // from any non-editable target to the composer, so
                            // "click the feed, start typing" still types into
                            // the prompt. :focus-visible stays off on a mouse
                            // click, so no ring appears either. Space is a
                            // printable key and goes to the composer, so PgDn,
                            // not Space, pages down.
                            tabIndex={0}
                            role="region"
                            aria-label="Conversation"
                            className="h-full overflow-auto @container outline-none focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-focus-ring"
                            onKeyDown={event => {
                              // Keyboard scrolling is engagement exactly as a
                              // wheel is: it means "I am reading back". Only
                              // keys on the scroller itself count; a key
                              // pressed inside a feed control is that control's.
                              if (event.target === event.currentTarget) onUserEngagement?.()
                            }}
                            onWheel={() => {
                              onUserEngagement?.()
                            }}
                            onPointerDown={() => {
                              onUserEngagement?.()
                            }}
                          >
                            {/* Container-query responsive (mobile-feed-rewrite Part A). This node
                             *  is SHARED with the desktop and with narrow tiled panes, so the
                             *  WIDEST step (@min-[768px]) restores the historical desktop classes
                             *  VERBATIM — wide output must not change (regression invariant). Only
                             *  narrow widths (phone, skinny tiles) diverge: they drop the max-w cap
                             *  and shrink the gutters, instead of eating 64px of px-8 on a ~375px
                             *  screen. The scroller above carries `@container` so these variants
                             *  respond to the FEED's own width, not the viewport — which is why a
                             *  narrow desktop tile benefits identically to a phone. */}
                            <div className="feed-column min-h-full flex flex-col gap-4 mx-auto px-3 pt-3 pb-6 @min-[480px]:px-5 @min-[480px]:pt-5 @min-[768px]:max-w-[880px] @min-[768px]:px-8 @min-[768px]:pt-6 @min-[768px]:pb-8">
                              {/* ONE owner rule for every visible feed surface.
                               *
                               * The old JSX rendered separate buckets in a fixed order:
                               * committed entries first, semantic history/current later,
                               * work last. That let a
                               * stale semantic history row mount under a newer submitted
                               * prompt, which looked exactly like "my user prompt never
                               * rendered" in real conversations. Feed now consumes the
                               * selector's single ordered item list so ownership,
                               * chronological placement, debug rows, and lazy-entry
                               * eagerness all share one render contract. Queued prompts
                               * remain composer-adjacent because they are pending input,
                               * not transcript history. */}
                              {renderItems.map(renderFeedItem)}
                              <div ref={endRef} />
                            </div>
                          </div>
                        </CodeRenderContext.Provider>
                      </LiveUnresolvedQuestionsContext.Provider>
                    </AskUserQuestionConditionContext.Provider>
                  </TaskNotificationsContext.Provider>
                </SubAgentsContext.Provider>
              </CommittedOperationDecisionContext.Provider>
            </ToolResultIndexContext.Provider>
          </ToolUseIndexContext.Provider>
        </RenderShapeCaptureProvider>
      </RenderingDebugProvider>
    </ProviderContext.Provider>
  )
}

